}

.form-field fieldset {
  border: 0;
  margin: 0;
  padding: 1.5rem;
}

legend {
  padding: 0;
  margin: 0 0 0.25rem;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--text);
  display: block;
  width: 100%;
}

.q-num {
  display: block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 0.25rem;
}

.help-text {
  margin: 0.5rem 0 1rem;
  font-size: 0.9375rem;
