AssistantMessageToolRequest(name='create', tool_call_id='toolu_01R8c2MuHm4i6t35HoAp5gJi', arguments={'path': '/workspace/sandbox/skills/building-accessible-ui/checkbox-group--framework-vanilla-js--style-modern/claude-opus-4.7__s4/script.js', 'file_text': '(function () {
  'use strict';

  const ANSWERS = {
    q1: ['java', 'rust'],
    q2: ['c', 'cpp'],
    q3: ['kotlin', 'scala', 'clojure'],
  };

  const form = document.getElementById('quiz-form');
  const status = document.getElementById('form-status');

  function getSelected(name) {
    return Array.from(
      form.querySelectorAll(`input[name="${name}"]:checked`)
    ).map((el) => el.value);
  }

  function arraysEqualAsSets(a, b) {
    if (a.length !== b.length) return false;
    const set = new Set(a);
    return b.every((v) => set.has(v));
  }

  form.addEventListener('submit', function (event) {
    event.preventDefault();

    const unanswered = [];
    let score = 0;

    Object.keys(ANSWERS).forEach((q) => {
      const picks = getSelected(q);
      if (picks.length === 0) unanswered.push(q);
      if (arraysEqualAsSets(picks, ANSWERS[q])) score += 1;
    });

    status.classList.remove('is-success', 'is-error');

    if (unanswered.length > 0) {
      status.textContent =
        'Error: Please answer every question before submitting (select at least one option per question).';
      status.classList.add('is-error');
      const firstUnanswered = form.querySelector(
        `input[name="${unanswered[0]}"]`
      );
      if (firstUnanswered) firstUnanswered.focus();
      return;
    }

    const total = Object.keys(ANSWERS).length;
    status.textContent = `You scored ${score} out of ${total}. ${
      score === total ? 'Perfect score!' : 'Review the questions and try again.'
    }`;
    status.classList.add(score === total ? 'is-success' : 'is-error');
  });

  form.addEventListener('reset', function () {
    status.textContent = '';
    status.classList.remove('is-success', 'is-error');
  });
})();
