+  console.log('INCOMPLETE:', results.incomplete.length);
+  for (const v of results.incomplete) {
+    console.log(' ?', v.id, '|', v.help);
+  }
+  process.exit(results.violations.length ? 1 : 0);
+})().catch(e => { console.error(e); process.exit(2); });
