            <label class="option"><input type="checkbox" name="q2" value="cpp"><span>C++</span></label>
            <label class="option"><input type="checkbox" name="q2" value="ruby"><span>Ruby</span></label>
            <label class="option"><input type="checkbox" name="q2" value="swift"><span>Swift</span></label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend><span class="q-num">Question 3</span> Which languages run primarily on the JVM?</legend>
          <div class="options">
            <label class="option"><input type="checkbox" name="q3" value="kotlin"><span>Kotlin</span></label>
            <label class="option"><input type="checkbox" name="q3" value="scala"><span>Scala</span></label>
            <label class="option"><input type="checkbox" name="q3" value="go"><span>Go</span></label>
            <label class="option"><input type="checkbox" name="q3" value="clojure"><span>Clojure</span></label>
          </div>
        </fieldset>
      </div>

      <div class="actions">
        <button type="submit" class="submit-btn">Submit answers</button>
        <button type="reset" class="reset-btn">Reset</button>
      </div>

