  <title>Computer Languages Quiz</title>
  <style>
    :root {
      --bg: #f6f7fb;
      --surface: #ffffff;
      --surface-2: #f1f3f9;
      --border: #e3e6ee;
      --border-strong: #c8cdd9;
      --text: #1a1d29;
      --text-muted: #525866;
      --accent: #4f46e5;
