      max-width: 680px;
      margin: 0 auto;
      padding: 3rem 1.25rem 4rem;
    }

    .page-header { margin-bottom: 2rem; }

    .eyebrow {
      margin: 0 0 0.5rem;
      font-size: 0.8125rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.75rem, 4vw, 2.25rem);
      font-weight: 700;
      letter-spacing: -0.02em;
    }

    .lede {
      margin: 0;
      color: var(--text-muted);
      font-size: 1.0625rem;
    }

    .quiz {
      display: flex;
      flex-direction: column;
      gap: 1rem;
    }

    .form-field {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow-sm);
      overflow: hidden;
    }

    .form-field fieldset {
      border: 0;
      margin: 0;
      padding: 1.5rem;
    }

    legend {
      padding: 0;
      margin: 0 0 0.25rem;
      font-size: 1.0625rem;
      font-weight: 600;
      color: var(--text);
      display: block;
      width: 100%;
    }

    .q-num {
      display: block;
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 0.25rem;
    }

    .help-text {
      margin: 0.5rem 0 1rem;
      font-size: 0.9375rem;
      color: #1a1d29;
      background: var(--accent-soft);
      border-left: 3px solid var(--accent);
      padding: 0.625rem 0.875rem;
      border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
    }

    .options {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
      gap: 0.625rem;
      margin-top: 1rem;
    }

    .option {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      padding: 0.875rem 1rem;
      background: var(--surface);
      border: 1.5px solid var(--border-strong);
      border-radius: var(--radius-sm);
      cursor: pointer;
      font-size: 0.9375rem;
      font-weight: 500;
      transition: border-color 120ms ease, background-color 120ms ease;
    }

    .option:hover {
      border-color: var(--accent);
      background: var(--surface-2);
    }

    .option input[type="checkbox"] {
      width: 1.125rem;
      height: 1.125rem;
      margin: 0;
      accent-color: var(--accent);
      cursor: pointer;
      flex-shrink: 0;
    }

    .option:has(input:checked) {
      border-color: var(--accent);
      background: var(--accent-soft);
    }

    .option:focus-within {
      outline: 3px solid var(--focus);
      outline-offset: 2px;
      border-color: var(--accent);
    }

    .option input[type="checkbox"]:focus-visible {
      outline: none;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      margin-top: 0.5rem;
    }

    button {
      font: inherit;
      cursor: pointer;
      border-radius: var(--radius-sm);
      padding: 0.75rem 1.25rem;
      font-weight: 600;
      font-size: 0.9375rem;
      transition: background-color 120ms ease, border-color 120ms ease, transform 80ms ease;
    }

    button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 2px;
    }

    .submit-btn {
      background: var(--accent);
      color: #fff;
      border: 1.5px solid var(--accent);
      box-shadow: var(--shadow-sm);
    }
    .submit-btn:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
    .submit-btn:active { transform: translateY(1px); }

    .reset-btn {
      background: var(--surface);
      color: var(--text);
      border: 1.5px solid var(--border-strong);
    }
    .reset-btn:hover { background: var(--surface-2); }

    .form-status {
      margin: 0.5rem 0 0;
      padding: 0;
      font-size: 0.9375rem;
      min-height: 1.25rem;
    }
    .form-status:not(:empty) {
      padding: 0.875rem 1rem;
      border-radius: var(--radius-sm);
      font-weight: 500;
    }
    .form-status.is-success {
      background: var(--success-soft);
      color: var(--success);
      border: 1px solid #a7f3d0;
    }
    .form-status.is-error {
      background: var(--error-soft);
      color: var(--error);
      border: 1px solid #fecdca;
    }

    @media (prefers-reduced-motion: reduce) {
      * { transition: none !important; }
    }

    @media (forced-colors: active) {
      .form-field { border: 1px solid CanvasText; }
      .option { border: 1px solid CanvasText; }
      .option:has(input:checked) { border: 2px solid Highlight; }
      .submit-btn { border: 1px solid ButtonText; }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>
  <main id="main" class="page">
    <header class="page-header">
      <p class="eyebrow">Knowledge check</p>
      <h1>Computer Languages Quiz</h1>
      <p class="lede">Three quick questions about programming languages. Each question may have more than one correct answer — pick all that apply.</p>
    </header>

    <form id="quiz-form" class="quiz" novalidate>
      <div class="form-field">
        <fieldset aria-describedby="q1-help">
          <legend><span class="q-num">Question 1</span> Which of the following are statically typed languages?</legend>
          <p id="q1-help" class="help-text">Tip: in a statically typed language, variable types are checked at compile time. Select all that apply.</p>
          <div class="options">
            <label class="option"><input type="checkbox" name="q1" value="java"><span>Java</span></label>
            <label class="option"><input type="checkbox" name="q1" value="python"><span>Python</span></label>
            <label class="option"><input type="checkbox" name="q1" value="rust"><span>Rust</span></label>
            <label class="option"><input type="checkbox" name="q1" value="javascript"><span>JavaScript</span></label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend><span class="q-num">Question 2</span> Which of these languages were originally created at Bell Labs?</legend>
          <div class="options">
            <label class="option"><input type="checkbox" name="q2" value="c"><span>C</span></label>
            <label class="option"><input type="checkbox" name="q2" value="cpp"><span>C++</span></label>
            <label class="option"><input type="checkbox" name="q2" value="ruby"><span>Ruby</span></label>
            <label class="option"><input type="checkbox" name="q2" value="swift"><span>Swift</span></label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend><span class="q-num">Question 3</span> Which languages run primarily on the JVM?</legend>
          <div class="options">
            <label class="option"><input type="checkbox" name="q3" value="kotlin"><span>Kotlin</span></label>
            <label class="option"><input type="checkbox" name="q3" value="scala"><span>Scala</span></label>
            <label class="option"><input type="checkbox" name="q3" value="go"><span>Go</span></label>
            <label class="option"><input type="checkbox" name="q3" value="clojure"><span>Clojure</span></label>
          </div>
        </fieldset>
      </div>

      <div class="actions">
        <button type="submit" class="submit-btn">Submit answers</button>
        <button type="reset" class="reset-btn">Reset</button>
      </div>

      <p id="form-status" class="form-status" aria-live="polite" role="status"></p>
    </form>
  </main>

  <script>
    (function () {
      'use strict';

      const ANSWERS = {
        q1: ['java', 'rust'],
        q2: ['c', 'cpp'],
        q3: ['kotlin', 'scala', 'clojure'],
      };

      const form = document.getElementById('quiz-form');
      const status = document.getElementById('form-status');

      function getSelected(name) {
        return Array.from(
          form.querySelectorAll('input[name="' + name + '"]:checked')
        ).map(function (el) { return el.value; });
      }

      function arraysEqualAsSets(a, b) {
        if (a.length !== b.length) return false;
        const set = new Set(a);
        return b.every(function (v) { return set.has(v); });
      }

      form.addEventListener('submit', function (event) {
        event.preventDefault();

        const unanswered = [];
        let score = 0;

        Object.keys(ANSWERS).forEach(function (q) {
          const picks = getSelected(q);
          if (picks.length === 0) unanswered.push(q);
          if (arraysEqualAsSets(picks, ANSWERS[q])) score += 1;
        });

        status.classList.remove('is-success', 'is-error');

        if (unanswered.length > 0) {
          status.textContent =
            'Error: Please answer every question before submitting (select at least one option per question).';
          status.classList.add('is-error');
          const firstUnanswered = form.querySelector(
            'input[name="' + unanswered[0] + '"]'
          );
          if (firstUnanswered) firstUnanswered.focus();
          return;
        }

        const total = Object.keys(ANSWERS).length;
        status.textContent =
          'You scored ' + score + ' out of ' + total + '. ' +
          (score === total ? 'Perfect score!' : 'Review the questions and try again.');
        status.classList.add(score === total ? 'is-success' : 'is-error');
      });

      form.addEventListener('reset', function () {
        status.textContent = '';
        status.classList.remove('is-success', 'is-error');
      });
    })();
  </script>
</body>
</html>
